#include <cassert>
int main() {
    Buffer empty(0);
    Buffer empty_copy(empty);
    Buffer empty_move(std::move(empty));
    assert(empty.size == 0 && !empty.data);
    assert(empty_copy.size == 0 && empty_move.size == 0);
    std::cout << "zero_length=PASS\n";

    Buffer original(3);
    original.data[0] = 11;
    original.data[1] = -2;
    original.data[2] = 99;
    Buffer copied(original);
    assert(copied.data.get() != original.data.get());
    assert(copied.data[0] == 11 && copied.data[1] == -2 && copied.data[2] == 99);
    copied.data[1] = 123;
    assert(original.data[1] == -2);
    std::cout << "deep_copy_independence=PASS\n";

    int* payload = copied.data.get();
    Buffer moved(std::move(copied));
    assert(moved.size == 3 && moved.data.get() == payload && moved.data[1] == 123);
    assert(copied.size == 0 && !copied.data);
    Buffer recopy(copied);
    Buffer remove(std::move(copied));
    assert(recopy.size == 0 && remove.size == 0 && !remove.data);
    std::cout << "move_and_moved_from_operations=PASS\n";

    for (std::size_t count : {std::size_t(0), std::size_t(3)}) {
        std::vector<Buffer> items;
        items.reserve(count);
        for (std::size_t i = 0; i < count; ++i) {
            items.emplace_back(3);
            for (std::size_t j = 0; j < 3; ++j)
                items[i].data[j] = static_cast<int>(10 * i + j);
        }
        const auto old_capacity = items.capacity();
        Buffer::copies = 0;
        Buffer::moves = 0;
        items.reserve(old_capacity + 1);
        assert(items.size() == count && items.capacity() >= old_capacity + 1);
        assert(Buffer::copies == 0 && Buffer::moves == static_cast<int>(count));
        for (std::size_t i = 0; i < count; ++i)
            for (std::size_t j = 0; j < 3; ++j)
                assert(items[i].data[j] == static_cast<int>(10 * i + j));
        std::cout << "vector count=" << count << " copies=" << Buffer::copies
                  << " moves=" << Buffer::moves << " values=PASS\n";
    }
}
